-- =============================================================================
-- Part 2: hand-written (ADR-0022)
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 2.1 Entitlement values must fit the feature type. One definition shared by
-- Feature defaults, PlanFeature and OrganisationFeatureOverride.
-- ---------------------------------------------------------------------------
CREATE FUNCTION app_check_entitlement_value(
  feature_type "FeatureType", enabled boolean, lim bigint, unlimited boolean, config jsonb
) RETURNS void
  LANGUAGE plpgsql IMMUTABLE
  AS $$
  BEGIN
    IF lim IS NOT NULL AND lim < 0 THEN
      RAISE EXCEPTION 'entitlement limit must be >= 0' USING ERRCODE = 'check_violation';
    END IF;
    IF feature_type = 'BOOLEAN' THEN
      IF lim IS NOT NULL OR unlimited OR config IS NOT NULL THEN
        RAISE EXCEPTION 'BOOLEAN entitlements take no limit or config' USING ERRCODE = 'check_violation';
      END IF;
    ELSIF feature_type = 'LIMIT' THEN
      IF config IS NOT NULL THEN
        RAISE EXCEPTION 'LIMIT entitlements take no config' USING ERRCODE = 'check_violation';
      END IF;
      IF enabled AND ((lim IS NOT NULL) = unlimited) THEN
        RAISE EXCEPTION 'an enabled LIMIT entitlement needs exactly one of limit or unlimited'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NOT enabled AND (lim IS NOT NULL OR unlimited) THEN
        RAISE EXCEPTION 'a disabled LIMIT entitlement takes no limit' USING ERRCODE = 'check_violation';
      END IF;
    ELSIF feature_type = 'CONFIGURATION' THEN
      IF lim IS NOT NULL OR unlimited THEN
        RAISE EXCEPTION 'CONFIGURATION entitlements take no limit' USING ERRCODE = 'check_violation';
      END IF;
      IF enabled AND (config IS NULL OR jsonb_typeof(config) <> 'object') THEN
        RAISE EXCEPTION 'an enabled CONFIGURATION entitlement needs a JSON object'
          USING ERRCODE = 'check_violation';
      END IF;
      IF config IS NOT NULL AND jsonb_typeof(config) <> 'object' THEN
        RAISE EXCEPTION 'entitlement config must be a JSON object' USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END
  $$;

CREATE FUNCTION app_check_feature_default() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
  BEGIN
    PERFORM app_check_entitlement_value(NEW.type, NEW."defaultEnabled", NEW."defaultLimit",
      NEW."defaultUnlimited", NEW."defaultConfig");
    RETURN NEW;
  END
  $$;

-- SECURITY DEFINER so the feature type is visible whichever role writes.
CREATE FUNCTION app_check_granted_entitlement() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
  DECLARE
    ftype "FeatureType";
  BEGIN
    SELECT type INTO ftype FROM "Feature" WHERE id = NEW."featureId";
    IF ftype IS NULL THEN
      RAISE EXCEPTION 'unknown feature' USING ERRCODE = 'foreign_key_violation';
    END IF;
    PERFORM app_check_entitlement_value(ftype, NEW.enabled, NEW."limit", NEW.unlimited, NEW.config);
    RETURN NEW;
  END
  $$;

REVOKE ALL ON FUNCTION app_check_entitlement_value("FeatureType", boolean, bigint, boolean, jsonb),
  app_check_feature_default(), app_check_granted_entitlement() FROM PUBLIC;

CREATE TRIGGER "Feature_check_default" BEFORE INSERT OR UPDATE ON "Feature"
  FOR EACH ROW EXECUTE FUNCTION app_check_feature_default();
CREATE TRIGGER "PlanFeature_check_value" BEFORE INSERT OR UPDATE ON "PlanFeature"
  FOR EACH ROW EXECUTE FUNCTION app_check_granted_entitlement();
CREATE TRIGGER "OrganisationFeatureOverride_check_value" BEFORE INSERT OR UPDATE ON "OrganisationFeatureOverride"
  FOR EACH ROW EXECUTE FUNCTION app_check_granted_entitlement();

