-- ---------------------------------------------------------------------------
-- 2.3 CHECK constraints and partial unique indexes (erd.md §6).
-- ---------------------------------------------------------------------------
ALTER TABLE "Plan"
  ADD CONSTRAINT "Plan_key_format" CHECK (key ~ '^[a-z][a-z0-9_]{1,39}$'),
  ADD CONSTRAINT "Plan_name_length" CHECK (char_length(btrim(name)) BETWEEN 1 AND 60),
  ADD CONSTRAINT "Plan_trial_days_range" CHECK ("trialDays" BETWEEN 0 AND 365);
ALTER TABLE "Feature"
  ADD CONSTRAINT "Feature_key_format" CHECK (key ~ '^[a-z][a-z0-9_]{1,39}$');
ALTER TABLE "PlanPrice"
  ADD CONSTRAINT "PlanPrice_amount_non_negative" CHECK (amount >= 0),
  ADD CONSTRAINT "PlanPrice_currency_format" CHECK (currency ~ '^[A-Z]{3}$');
CREATE UNIQUE INDEX "PlanPrice_one_active_per_interval_currency"
  ON "PlanPrice" ("planId", "interval", currency) WHERE active;

ALTER TABLE "OrganisationFeatureOverride"
  ADD CONSTRAINT "OrganisationFeatureOverride_reason_length" CHECK (char_length(btrim(reason)) BETWEEN 3 AND 500);

ALTER TABLE "Subscription"
  ADD CONSTRAINT "Subscription_source_provider" CHECK (
    (source = 'MANUAL' AND provider IS NULL AND "providerSubscriptionId" IS NULL)
    OR (source = 'MOCK' AND provider = 'MOCK' AND "providerSubscriptionId" IS NOT NULL)
    OR (source = 'PAYMENT_PROVIDER' AND provider IN ('RAZORPAY', 'STRIPE') AND "providerSubscriptionId" IS NOT NULL)
  ),
  ADD CONSTRAINT "Subscription_trial_dates" CHECK (
    (status <> 'TRIAL' OR "trialEndsAt" IS NOT NULL)
    AND ("trialStartsAt" IS NULL OR "trialEndsAt" IS NULL OR "trialStartsAt" < "trialEndsAt")
  ),
  ADD CONSTRAINT "Subscription_past_due_dates" CHECK (
    status <> 'PAST_DUE' OR ("pastDueSince" IS NOT NULL AND "graceEndsAt" IS NOT NULL)
  ),
  ADD CONSTRAINT "Subscription_cancelled_dates" CHECK (
    status <> 'CANCELLED' OR ("cancelledAt" IS NOT NULL AND "expiresAt" IS NOT NULL)
  ),
  ADD CONSTRAINT "Subscription_expired_dates" CHECK (status <> 'EXPIRED' OR "endedAt" IS NOT NULL),
  ADD CONSTRAINT "Subscription_period_order" CHECK (
    "currentPeriodStart" IS NULL OR "currentPeriodEnd" IS NULL OR "currentPeriodStart" < "currentPeriodEnd"
  );
CREATE UNIQUE INDEX "Subscription_one_live_per_organisation"
  ON "Subscription" ("organisationId") WHERE status <> 'EXPIRED';

ALTER TABLE "SubscriptionEvent"
  ADD CONSTRAINT "SubscriptionEvent_reason_length" CHECK (reason IS NULL OR char_length(reason) <= 500),
  ADD CONSTRAINT "SubscriptionEvent_note_length" CHECK (note IS NULL OR char_length(note) <= 2000);

ALTER TABLE "BillingWebhookEvent"
  ADD CONSTRAINT "BillingWebhookEvent_attempts_non_negative" CHECK (attempts >= 0);

ALTER TABLE "UsageCounter"
  ADD CONSTRAINT "UsageCounter_value_non_negative" CHECK (value >= 0);

-- ---------------------------------------------------------------------------
-- 2.4 Tenant ownership columns are immutable (function from the M1 migration).
-- SubscriptionEvent is append-only: nobody but the owner may UPDATE/DELETE.
-- ---------------------------------------------------------------------------
CREATE TRIGGER "Subscription_immutable_owner" BEFORE UPDATE ON "Subscription"
  FOR EACH ROW EXECUTE FUNCTION app_forbid_owner_change();
CREATE TRIGGER "OrganisationFeatureOverride_immutable_owner" BEFORE UPDATE ON "OrganisationFeatureOverride"
  FOR EACH ROW EXECUTE FUNCTION app_forbid_owner_change();
CREATE TRIGGER "UsageCounter_immutable_owner" BEFORE UPDATE ON "UsageCounter"
  FOR EACH ROW EXECUTE FUNCTION app_forbid_owner_change();
CREATE TRIGGER "BillingCustomer_immutable_owner" BEFORE UPDATE ON "BillingCustomer"
  FOR EACH ROW EXECUTE FUNCTION app_forbid_owner_change();

-- ---------------------------------------------------------------------------
-- 2.5 Row-level security for organisation-scoped billing tables.
-- ---------------------------------------------------------------------------
ALTER TABLE "Subscription" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Subscription" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "Subscription"
  USING ("organisationId" = app_current_org()) WITH CHECK ("organisationId" = app_current_org());

ALTER TABLE "SubscriptionEvent" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "SubscriptionEvent" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "SubscriptionEvent"
  USING ("organisationId" = app_current_org()) WITH CHECK ("organisationId" = app_current_org());

ALTER TABLE "OrganisationFeatureOverride" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "OrganisationFeatureOverride" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "OrganisationFeatureOverride"
  USING ("organisationId" = app_current_org()) WITH CHECK ("organisationId" = app_current_org());

ALTER TABLE "UsageCounter" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "UsageCounter" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "UsageCounter"
  USING ("organisationId" = app_current_org()) WITH CHECK ("organisationId" = app_current_org());

ALTER TABLE "BillingCustomer" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "BillingCustomer" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "BillingCustomer"
  USING ("organisationId" = app_current_org()) WITH CHECK ("organisationId" = app_current_org());

ALTER TABLE "BillingWebhookEvent" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "BillingWebhookEvent" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "BillingWebhookEvent"
  USING ("organisationId" = app_current_org()) WITH CHECK ("organisationId" = app_current_org());

-- ---------------------------------------------------------------------------
-- 2.6 Grants (ADR-0022 §8). Nothing to PUBLIC.
-- ---------------------------------------------------------------------------

-- Application role: reads the catalogue and its own organisation's
-- subscription and overrides (not the staff reason/author columns); maintains
-- its own usage counters. It can never write subscriptions, events or
-- overrides: merchants have no path to change their plan.
GRANT SELECT ON "Plan", "PlanPrice", "Feature", "PlanFeature" TO storevia_app;
GRANT SELECT ON "Subscription" TO storevia_app;
GRANT SELECT (id, "organisationId", "featureId", enabled, "limit", unlimited, config, "expiresAt")
  ON "OrganisationFeatureOverride" TO storevia_app;
GRANT SELECT, INSERT ON "UsageCounter" TO storevia_app;
GRANT UPDATE (value, "updatedAt") ON "UsageCounter" TO storevia_app;

-- System role: webhook pipeline and expiry sweep (packages/billing).
GRANT SELECT ON "Plan", "PlanPrice", "Feature", "PlanFeature" TO storevia_system;
GRANT SELECT, INSERT ON "Subscription" TO storevia_system;
GRANT UPDATE ("planId", status, "billingInterval", "startedAt", "trialStartsAt", "trialEndsAt",
  "currentPeriodStart", "currentPeriodEnd", "expiresAt", "cancelledAt", "pastDueSince",
  "graceEndsAt", "endedAt", "providerSyncedAt", "updatedAt") ON "Subscription" TO storevia_system;
GRANT INSERT ON "SubscriptionEvent" TO storevia_system;
GRANT SELECT ON "BillingCustomer" TO storevia_system;
GRANT SELECT, INSERT ON "BillingWebhookEvent" TO storevia_system;
GRANT UPDATE (status, "organisationId", attempts, outcome, "lastError", "processedAt")
  ON "BillingWebhookEvent" TO storevia_system;

-- Platform-admin role: reads everything billing-related; writes only what
-- audited staff actions need.
GRANT SELECT ON "Plan", "PlanPrice", "Feature", "PlanFeature", "Subscription", "SubscriptionEvent",
  "OrganisationFeatureOverride", "UsageCounter", "BillingCustomer", "BillingWebhookEvent"
  TO storevia_platform;
GRANT INSERT ON "Subscription" TO storevia_platform;
GRANT UPDATE ("planId", status, "billingInterval", "startedAt", "trialStartsAt", "trialEndsAt",
  "currentPeriodStart", "currentPeriodEnd", "expiresAt", "cancelledAt", "pastDueSince",
  "graceEndsAt", "endedAt", "updatedAt") ON "Subscription" TO storevia_platform;
GRANT INSERT ON "SubscriptionEvent" TO storevia_platform;
GRANT INSERT, DELETE ON "OrganisationFeatureOverride" TO storevia_platform;
GRANT UPDATE (enabled, "limit", unlimited, config, reason, "expiresAt", "updatedById", "updatedAt")
  ON "OrganisationFeatureOverride" TO storevia_platform;
GRANT INSERT ON "UsageCounter" TO storevia_platform;
GRANT UPDATE (value, "updatedAt") ON "UsageCounter" TO storevia_platform;
GRANT INSERT ON "BillingCustomer" TO storevia_platform;

-- ---------------------------------------------------------------------------
-- 2.7 Backfill gauge counters for organisations that existed before M2.
-- ---------------------------------------------------------------------------
INSERT INTO "UsageCounter" ("organisationId", "featureId", "scopeKey", period, value, "updatedAt")
SELECT o.id, f.id, '', 'all',
  (SELECT count(*) FROM "Store" s WHERE s."organisationId" = o.id AND s.status <> 'ARCHIVED'),
  CURRENT_TIMESTAMP
FROM "Organisation" o CROSS JOIN "Feature" f
WHERE f.key = 'store_count';

INSERT INTO "UsageCounter" ("organisationId", "featureId", "scopeKey", period, value, "updatedAt")
SELECT o.id, f.id, '', 'all',
  (SELECT count(*) FROM "Membership" m WHERE m."organisationId" = o.id),
  CURRENT_TIMESTAMP
FROM "Organisation" o CROSS JOIN "Feature" f
WHERE f.key = 'staff_accounts';
